<body>
  <main id="app"></main>
  <script type="module">
    const app = document.querySelector('#app');
    const escapeText = (value) => String(value).replace(/[&<>"']/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[char]);

    async function showProjects() {
      app.innerHTML = `
        <h1>Workboard</h1>
        <form id="create-project">
          <label for="project-name" class="visually-hidden">Project name</label>
          <input id="project-name" name="name" type="text" aria-label="Project name" autocomplete="off">
          <button type="submit">Create project</button>
        </form>
        <div id="form-message" role="alert" aria-live="polite"></div>
        <div class="project-controls"><label for="project-filter">Project filter</label><select id="project-filter"><option>Active</option><option>Archived</option></select></div>
        <section id="project-list" class="project-list" aria-label="Projects"></section>`;
      const list = app.querySelector('#project-list');
      const filter = app.querySelector('#project-filter');
      let projects = [];
      const loadProjects = async () => {
        const response = await fetch('/api/projects');
        projects = await response.json();
        renderProjects();
      };
      const renderProjects = () => {
        const archived = filter.value === 'Archived';
        list.innerHTML = projects.filter((project) => project.archived === archived).map((project) => `
          <div class="project-row" data-testid="project-row">
            <span class="project-name">${escapeText(project.name)}</span>
            <span class="project-summary" data-testid="project-summary">${project.completed_count}/${project.total_count} completed</span>
            <span class="project-actions"><button type="button" data-action="open" data-project-id="${project.id}">Open project</button>
            <button type="button" data-action="${archived ? 'restore' : 'archive'}" data-project-id="${project.id}">${archived ? 'Restore project' : 'Archive project'}</button></span>
          </div>`).join('');
      };
      await loadProjects();
      filter.addEventListener('change', renderProjects);
      app.querySelector('#create-project').addEventListener('submit', async (event) => {
        event.preventDefault();
        const input = app.querySelector('#project-name');
        const name = input.value.trim();
        const message = app.querySelector('#form-message');
        if (!name) {
          message.textContent = 'Project name is required';
          return;
        }
        const response = await fetch('/api/projects', {
          method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ name })
        });
        if (!response.ok) {
          const result = await response.json();
          message.textContent = result.error || 'Could not create project';
          return;
        }
        message.textContent = '';
        input.value = '';
        await loadProjects();
      });
      list.addEventListener('click', (event) => {
        const button = event.target.closest('button[data-project-id]');
        if (!button) return;
        if (button.dataset.action === 'open') { location.href = `/projects/${button.dataset.projectId}`; return; }
        fetch(`/api/projects/${button.dataset.projectId}/${button.dataset.action}`, { method: 'POST' }).then(loadProjects);
      });
    }

    async function showProject(id) {
      const response = await fetch(`/api/projects/${encodeURIComponent(id)}`);
      if (!response.ok) {
        app.innerHTML = '<h1>Project not found</h1><button id="back" type="button">Projects</button>';
      } else {
        const project = await response.json();
        app.innerHTML = `<section id="project-view"><button id="back" type="button">Projects</button><h1>${escapeText(project.name)}</h1>
          ${project.archived ? '<p>Archived project</p>' : ''}
          <form id="rename-project"><label for="new-project-name" class="visually-hidden">New project name</label><input id="new-project-name" type="text" aria-label="New project name" autocomplete="off" ${project.archived ? 'disabled' : ''}><button type="submit" ${project.archived ? 'disabled' : ''}>Rename project</button></form>
          <div id="rename-message" role="alert" aria-live="polite"></div>
          <form id="create-task"><label for="task-title" class="visually-hidden">Task title</label><input id="task-title" type="text" aria-label="Task title" autocomplete="off" ${project.archived ? 'disabled' : ''}><button type="submit" ${project.archived ? 'disabled' : ''}>Create task</button></form>
          <div id="task-message" role="alert" aria-live="polite"></div>
          <div class="task-controls"><label for="task-filter">Task filter</label><select id="task-filter"><option>All</option><option>Open</option><option>Completed</option></select></div>
          <div class="task-controls"><label for="priority-filter">Priority filter</label><select id="priority-filter"><option>All</option><option>Low</option><option>Normal</option><option>High</option></select></div>
          <section id="task-list" class="task-list" aria-label="Tasks"></section></section>`;
        const list = app.querySelector('#task-list');
        const filter = app.querySelector('#task-filter');
        const priorityFilter = app.querySelector('#priority-filter');
        let tasks = [];
        const renderTasks = () => {
          const mode = filter.value;
          const selectedPriority = priorityFilter.value;
          const visible = tasks.filter((task) =>
            (mode === 'All' || (mode === 'Completed' ? task.completed : !task.completed)) &&
            (selectedPriority === 'All' || task.priority === selectedPriority));
          list.innerHTML = visible.map((task) => `<div class="task-row" data-testid="task-row"><input type="checkbox" data-task-id="${task.id}" aria-label="Complete ${escapeText(task.title)}" ${task.completed ? 'checked' : ''} ${project.archived ? 'disabled' : ''}><span class="task-name">${escapeText(task.title)}</span><select data-priority-task-id="${task.id}" aria-label="Task priority" ${project.archived ? 'disabled' : ''}><option ${task.priority === 'Low' ? 'selected' : ''}>Low</option><option ${task.priority === 'Normal' ? 'selected' : ''}>Normal</option><option ${task.priority === 'High' ? 'selected' : ''}>High</option></select><input type="text" data-rename-task-id="${task.id}" aria-label="New task title" autocomplete="off" ${project.archived ? 'disabled' : ''}><button type="button" data-rename-task-id="${task.id}" ${project.archived ? 'disabled' : ''}>Rename task</button></div>`).join('');
        };
        const loadTasks = async () => {
          const result = await fetch(`/api/projects/${encodeURIComponent(id)}/tasks`);
          tasks = result.ok ? await result.json() : [];
          renderTasks();
        };
        await loadTasks();
        app.querySelector('#rename-project').addEventListener('submit', async (event) => {
          event.preventDefault();
          const input = app.querySelector('#new-project-name');
          const name = input.value.trim();
          const message = app.querySelector('#rename-message');
          if (!name) { message.textContent = 'Project name is required'; return; }
          const result = await fetch(`/api/projects/${encodeURIComponent(id)}/rename`, {
            method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ name })
          });
          if (!result.ok) { message.textContent = (await result.json()).error || 'Could not rename project'; return; }
          project.name = name;
          app.querySelector('#project-view h1').textContent = name;
          input.value = '';
          message.textContent = '';
        });
        filter.addEventListener('change', renderTasks);
        priorityFilter.addEventListener('change', renderTasks);
        list.addEventListener('change', async (event) => {
          const prioritySelect = event.target.closest('select[data-priority-task-id]');
          if (prioritySelect) {
            const result = await fetch(`/api/tasks/${prioritySelect.dataset.priorityTaskId}/priority`, {
              method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ priority: prioritySelect.value })
            });
            if (result.ok) {
              const task = tasks.find((item) => item.id === Number(prioritySelect.dataset.priorityTaskId));
              if (task) task.priority = prioritySelect.value;
              renderTasks();
            } else {
              await loadTasks();
            }
            return;
          }
          const renameInput = event.target.closest('input[data-rename-task-id]');
          if (renameInput) return;
          const checkbox = event.target.closest('input[data-task-id]');
          if (!checkbox) return;
          await fetch(`/api/tasks/${checkbox.dataset.taskId}`, { method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ completed: checkbox.checked }) });
          const task = tasks.find((item) => item.id === Number(checkbox.dataset.taskId));
          if (task) task.completed = checkbox.checked;
          renderTasks();
        });
        list.addEventListener('click', async (event) => {
          const button = event.target.closest('button[data-rename-task-id]');
          if (!button) return;
          const task = tasks.find((item) => item.id === Number(button.dataset.renameTaskId));
          const input = list.querySelector(`input[data-rename-task-id="${button.dataset.renameTaskId}"]`);
          const title = input.value.trim();
          const message = app.querySelector('#task-message');
          if (!title) { message.textContent = 'Task title is required'; return; }
          const result = await fetch(`/api/tasks/${encodeURIComponent(button.dataset.renameTaskId)}/rename`, {
            method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ title })
          });
          if (!result.ok) { message.textContent = (await result.json()).error || 'Could not rename task'; return; }
          if (task) task.title = title;
          message.textContent = '';
          renderTasks();
        });
        app.querySelector('#create-task').addEventListener('submit', async (event) => {
          event.preventDefault();
          const input = app.querySelector('#task-title');
          const title = input.value.trim();
          const message = app.querySelector('#task-message');
          if (!title) { message.textContent = 'Task title is required'; return; }
          const result = await fetch(`/api/projects/${encodeURIComponent(id)}/tasks`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ title }) });
          if (!result.ok) { message.textContent = (await result.json()).error || 'Could not create task'; return; }
          message.textContent = '';
          input.value = '';
          filter.value = 'All';
          await loadTasks();
        });
      }
      app.querySelector('#back').addEventListener('click', () => { location.href = '/'; });
    }

    const match = location.pathname.match(/^\/projects\/(\d+)$/);
    if (match) await showProject(match[1]);
    else await showProjects();
  </script>
</body>
